export fn feistel_cipher_normalized(a: ?[*]const i64, n: usize) callconv(.c) i64 { if(a==null or n!=3)return -1;const input=a.?;const mode=input[0];const kv=input[1];if(mode<0 or mode>1 or kv<1 or kv>4294967295)return -1;const key:u32=@intCast(kv);for(0..32)|i|{if(roundKey(key,@intCast(i))==0)return -1;}const b:u64=@bitCast(input[2]);var l:u32=@truncate(b>>32);var r:u32=@truncate(b);if(mode==0){for(0..32)|i|{const rk=roundKey(key,@intCast(i));const t=r^f(l,rk);r=l;l=t;}}else{var i:i32=31;while(i>=0):(i-=1){const rk=roundKey(key,@intCast(i));const t=l^f(r,rk);l=r;r=t;}}return @bitCast((@as(u64,l)<<32)|r);}
fn roundKey(key:u32,round:u32)u32{var p:u32=1;for(0..round+2)|_|{p*%=key;}return p^key;}
fn f(initial:u32,key:u32)u32{var x=initial;for(0..32)|_|{x=((x^0x55555555)*%x)%key;x^=key;}return x;}
